function act(obs, mem) {
  if (!mem.init) {
    mem.init = true;
    mem.stuck = 0;
    mem.backing = 0;
    mem.avoidDir = 1;
    mem.prevDist = 10;
  }
  const dx = obs.goalX - obs.x;
  const dy = obs.goalY - obs.y;
  const distToGoal = Math.sqrt(dx * dx + dy * dy);
  if (distToGoal < 1) return { left: 0, right: 0 };

  let gdx = dx, gdy = dy;
  const m = 2.0;
  if (obs.x < m) gdx += (m - obs.x) * 3;
  if (obs.x > 40 - m) gdx -= (obs.x - (40 - m)) * 3;
  if (obs.y < m) gdy += (m - obs.y) * 3;
  if (obs.y > 40 - m) gdy -= (obs.y - (40 - m)) * 3;

  let desiredHeading = Math.atan2(gdy, gdx) * 180 / Math.PI;
  let headingErr = desiredHeading - obs.heading;
  while (headingErr > 180) headingErr -= 360;
  while (headingErr < -180) headingErr += 360;

  const dist = obs.distanceAhead;
  if (mem.backing > 0) {
    mem.backing--;
    mem.prevDist = dist;
    return { left: -0.4, right: -0.4 };
  }

  if (dist < 4 && mem.prevDist >= 4) {
    mem.avoidDir = headingErr >= 0 ? 1 : -1;
  }

  let base = 1.0;
  let steer = 0;
  const kP = 0.02;

  if (dist < 1.2) {
    base = 0;
    steer = mem.avoidDir * 0.7;
    mem.stuck++;
  } else if (dist < 2.5) {
    base = 0.4;
    steer = mem.avoidDir * 0.6 + kP * headingErr * 0.2;
    mem.stuck++;
  } else if (dist < 4) {
    base = 0.7;
    steer = mem.avoidDir * 0.35 + kP * headingErr * 0.4;
    mem.stuck++;
  } else {
    steer = kP * headingErr;
    mem.stuck = 0;
  }

  if (mem.stuck > 100) {
    mem.stuck = 0;
    mem.backing = 30;
    mem.prevDist = dist;
    return { left: -0.4, right: -0.4 };
  }

  steer = Math.max(-0.8, Math.min(0.8, steer));
  let left = base - steer;
  let right = base + steer;
  left = Math.max(-1, Math.min(1, left));
  right = Math.max(-1, Math.min(1, right));
  mem.prevDist = dist;
  return { left, right };
}

