function act(obs, mem) {
  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function wrap(a) {
    while (a > 180) a -= 360;
    while (a < -180) a += 360;
    return a;
  }

  var now = Number(obs.t);
  if (!(now >= 0)) now = 0;

  if (!mem._ae1 || (mem._ae1Last !== undefined && now < mem._ae1Last)) {
    mem._ae1 = true;
    mem._ae1Last = now;
    mem.mode = 0;
    mem.stage = 0;
    mem.side = 1;
    mem.flip = 1;
    mem.coolUntil = 0;
  }
  mem._ae1Last = now;

  var x = Number(obs.x);
  var y = Number(obs.y);
  var gx = Number(obs.goalX);
  var gy = Number(obs.goalY);
  var heading = Number(obs.heading);
  var speed = Number(obs.speed);
  var d = Number(obs.distanceAhead);

  if (!(speed > 0)) speed = 0;
  if (!(d >= 0)) d = 10;

  var toGoalX = gx - x;
  var toGoalY = gy - y;
  var goalDist = Math.hypot(toGoalX, toGoalY);

  if (goalDist < 0.8) {
    return { left: 0, right: 0 };
  }

  var hr = heading * Math.PI / 180;
  var fx = Math.cos(hr);
  var fy = Math.sin(hr);
  var nx = -fy;
  var ny = fx;

  var wallRay = 1e9;
  if (fx > 0.0001) wallRay = Math.min(wallRay, (40 - x) / fx);
  if (fx < -0.0001) wallRay = Math.min(wallRay, (0 - x) / fx);
  if (fy > 0.0001) wallRay = Math.min(wallRay, (40 - y) / fy);
  if (fy < -0.0001) wallRay = Math.min(wallRay, (0 - y) / fy);

  var wallFacing =
    wallRay > 0 &&
    wallRay < 7 &&
    d >= wallRay - 1.4 &&
    d < wallRay + 1.4;

  var edge = Math.min(x, 40 - x, y, 40 - y);

  if (!mem.mode &&
      now >= (mem.coolUntil || 0) &&
      d < 3.5 + Math.min(1.5, speed * 0.75) &&
      d < 9.5 &&
      !wallFacing) {
    var centerDistance = d + 1.4;
    var cx = x + fx * centerDistance;
    var cy = y + fy * centerDistance;
    var clear = 3.4;

    function sideCost(s) {
      var wx = cx + nx * s * clear;
      var wy = cy + ny * s * clear;
      var e = Math.min(wx, 40 - wx, wy, 40 - wy);
      var cost = Math.hypot(gx - wx, gy - wy);
      if (e < 2) cost += (2 - e) * 25;
      if (e < 0) cost += 1000;
      return cost;
    }

    var leftCost = sideCost(1);
    var rightCost = sideCost(-1);
    var side;
    if (Math.abs(leftCost - rightCost) < 0.25) {
      side = mem.flip;
    } else {
      side = leftCost < rightCost ? 1 : -1;
    }

    mem.flip = -side;
    mem.mode = 1;
    mem.stage = 1;
    mem.side = side;
    mem.cx = cx;
    mem.cy = cy;
    mem.tx = cx + nx * side * clear;
    mem.ty = cy + ny * side * clear;
    mem.px = cx + fx * 3.8 + nx * side * clear;
    mem.py = cy + fy * 3.8 + ny * side * clear;
  }

  if (mem.mode) {
    if (mem.stage === 1 &&
        Math.hypot(x - mem.tx, y - mem.ty) < 0.75) {
      mem.stage = 2;
    }

    if (mem.stage === 2 &&
        Math.hypot(x - mem.px, y - mem.py) < 0.8 &&
        d > 1.2) {
      mem.mode = 0;
      mem.stage = 0;
      mem.coolUntil = now + 0.7;
    }
  }

  if (mem.mode && d < 0.95) {
    var s = mem.side || 1;
    return {
      left: clamp(-0.58 * s, -1, 1),
      right: clamp(0.58 * s, -1, 1)
    };
  }

  var vx;
  var vy;

  if (mem.mode) {
    if (mem.stage === 1) {
      vx = mem.tx - x;
      vy = mem.ty - y;
    } else {
      vx = mem.px - x;
      vy = mem.py - y;
    }
  } else {
    var gl = Math.max(0.001, goalDist);
    vx = toGoalX / gl;
    vy = toGoalY / gl;

    if (x < 3) vx += 2 + (3 - x) * 3;
    if (x > 37) vx -= 2 + (x - 37) * 3;
    if (y < 3) vy += 2 + (3 - y) * 3;
    if (y > 37) vy -= 2 + (y - 37) * 3;
  }

  var desired = Math.atan2(vy, vx) * 180 / Math.PI;
  var error = wrap(desired - heading);
  var ae = Math.abs(error);
  var turn = clamp(error / 60, -1, 1);
  var base;

  if (ae > 115) base = 0;
  else if (ae > 80) base = 0.12;
  else if (ae > 45) base = 0.40;
  else if (ae > 20) base = 0.62;
  else base = 0.72;

  if (mem.mode && d < 2) base = Math.min(base, 0.18);
  if (edge < 4) base *= clamp(edge / 4, 0.2, 1);

  if (ae > 115) {
    var turnSign = error >= 0 ? 1 : -1;
    return {
      left: -0.55 * turnSign,
      right: 0.55 * turnSign
    };
  }

  var differential = 0.62 * turn;
  return {
    left: clamp(base - differential, -1, 1),
    right: clamp(base + differential, -1, 1)
  };
}

