  if (!isFinite(y)) y = 20;
  if (!isFinite(gx)) gx = 20;
  if (!isFinite(gy)) gy = 20;
  if (!isFinite(heading)) heading = 0;
  if (!isFinite(speed)) speed = 0;
  if (!(d >= 0)) d = 10;
  d = clamp(d, 0, 10);

  if (mem.prevH !== undefined && mem.prevT !== undefined) {
    var dt = now - mem.prevT;
    if (dt > 0.001 && dt < 0.5) {
      var rawOmega = wrap(heading - mem.prevH) / dt;
      rawOmega = clamp(rawOmega, -600, 600);
      mem.omega = 0.65 * mem.omega + 0.35 * rawOmega;
    }
  }
  mem.prevH = heading;
  mem.prevT = now;

  function emit(l, r, urgent) {
    var step = urgent ? 0.28 : 0.10;
    if (!isFinite(mem.outL)) mem.outL = 0;
    if (!isFinite(mem.outR)) mem.outR = 0;
    mem.outL += clamp(l - mem.outL, -step, step);
    mem.outR += clamp(r - mem.outR, -step, step);
    mem.outL = clamp(mem.outL, -1, 1);
    mem.outR = clamp(mem.outR, -1, 1);
    return { left: mem.outL, right: mem.outR };
  }

