  var toGoalY = gy - y;
  var goalDist = Math.hypot(toGoalX, toGoalY);

  if (goalDist < 0.82) {
    mem.av = 0;
    var brake = speed > 0.35 ? -0.32 : 0;
    return emit(brake, brake, true);
  }

  var hr = heading * Math.PI / 180;
  var fx = Math.cos(hr);
  var fy = Math.sin(hr);
  var nx = -fy;
  var ny = fx;

  var wallRay = 1e9;
  var wallNX = 0;
  var wallNY = 0;

  function considerWall(r, wx, wy) {
    if (r >= 0 && r < wallRay) {
      wallRay = r;
      wallNX = wx;
      wallNY = wy;
    }
  }

  if (fx > 0.00001) considerWall((40 - x) / fx, -1, 0);
  if (fx < -0.00001) considerWall((0 - x) / fx, 1, 0);
  if (fy > 0.00001) considerWall((40 - y) / fy, 0, -1);
  if (fy < -0.00001) considerWall((0 - y) / fy, 0, 1);

