        Math.hypot(gx - q2x, gy - q2y) +
        0.18 * Math.hypot(gx - q3x, gy - q3y);

      if (e < 2.0) cost += (2.0 - e) * 32;
      if (e < 0) cost += 10000;
      return cost;
    }

    var leftCost = sideCost(1);
    var rightCost = sideCost(-1);
    var side;

    if (Math.abs(leftCost - rightCost) < 0.45) {
      side = mem.flip >= 0 ? 1 : -1;
    } else {
      side = leftCost < rightCost ? 1 : -1;
    }

    mem.flip = -side;
    mem.av = 1;
    mem.stage = 1;
    mem.side = side;
    mem.avSince = now;
    mem.ofx = fx;
    mem.ofy = fy;
    mem.onx = nx;
    mem.ony = ny;
    mem.ox = ox;
    mem.oy = oy;
    mem.clear = clear;

    mem.tx1 = ox + fx * p1Long + nx * side * clear;
    mem.ty1 = oy + fy * p1Long + ny * side * clear;
    mem.tx2 = ox + fx * p2Long + nx * side * clear;
    mem.ty2 = oy + fy * p2Long + ny * side * clear;
    mem.tx3 = ox + fx * p3Long + nx * side * clear * 0.68;
    mem.ty3 = oy + fy * p3Long + ny * side * clear * 0.68;
