      tvx = mem.tx1 - x;
      tvy = mem.ty1 - y;
      if (d < 3.8) slow = 0.62;
    } else if (mem.stage === 2) {
      tvx = mem.tx2 - x;
      tvy = mem.ty2 - y;
      if (d < 3.8) slow = 0.55;
    } else {
      tvx = mem.tx3 - x;
      tvy = mem.ty3 - y;
      if (d < 3.8) slow = 0.55;
    }
  } else {
    tvx = toGoalX;
    tvy = toGoalY;

    if (d < 8.2 && !wallHit) {
      slow = d < 3 ? 0.42 : (d < 5 ? 0.68 : 1);
    }

    if (goalDist < 5) {
      slow *= clamp((goalDist - 0.7) / 4.3, 0.16, 1);
    }
