  var boundaryMargin = 2.2;
  if (x < boundaryMargin) tvx += (boundaryMargin - x) * 2.6;
  if (x > 40 - boundaryMargin) tvx -= (x - (40 - boundaryMargin)) * 2.6;
  if (y < boundaryMargin) tvy += (boundaryMargin - y) * 2.6;
  if (y > 40 - boundaryMargin) tvy -= (y - (40 - boundaryMargin)) * 2.6;

  if (wallHit) {
    var wallPush = Math.max(0, 6 - wallRay) * 2.4;
    if (wallRay < 3) wallPush += (3 - wallRay) * 3.0;
    tvx += wallNX * wallPush;
    tvy += wallNY * wallPush;
