  var desired = Math.atan2(tvy, tvx) * 180 / Math.PI;
  var error = wrap(desired - heading);
  var ae = Math.abs(error);

  var base;
  if (ae > 110) base = 0.02;
  else if (ae > 82) base = 0.12;
  else if (ae > 57) base = 0.32;
  else if (ae > 31) base = 0.55;
