  right = clamp(right, -1, 1);

  var urgent =
    (mem.av && d < 1.8 && !wallHit) ||
    (wallHit && wallRay < 3.2);

  return emit(left, right, urgent);
}

function act(obs, mem) {
  mem = mem || {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const wrap = (a) => ((a + 180) % 360 + 360) % 360 - 180;

  const x = Number.isFinite(obs.x) ? obs.x : 0;
  const y = Number.isFinite(obs.y) ? obs.y : 0;
  const heading = Number.isFinite(obs.heading) ? obs.heading : 0;
  const speed = Number.isFinite(obs.speed) ? Math.max(0, obs.speed) : 0;
  const range = Number.isFinite(obs.distanceAhead) ? obs.distanceAhead : 10;
  const dx = obs.goalX - x;
  const dy = obs.goalY - y;
  const goalDist = Math.hypot(dx, dy);
  const goalHeading = Math.atan2(dy, dx) * 180 / Math.PI;

  if (goalDist < 0.82) return { left: 0, right: 0 };

  let targetHeading = goalHeading;
  let avoiding = false;

  if (mem.avoidTicks > 0) {
    avoiding = true;

    if (!mem.avoidBumped && range < 2.4) {
      mem.avoidHeading = wrap(mem.avoidHeading + 25 * mem.avoidSide);
      mem.avoidTicks = Math.max(mem.avoidTicks, 18);
      mem.avoidBumped = true;
    }

    targetHeading = mem.avoidHeading;
    mem.avoidTicks -= 1;
  } else {
    const triggerRange = 4.2 + Math.min(1.0, speed * 0.25);

    if (range < triggerRange && goalDist > 0.9) {
      const plusError = Math.abs(wrap(heading + 78 - goalHeading));
      const minusError = Math.abs(wrap(heading - 78 - goalHeading));
      let side = mem.avoidSide || 1;

      if (plusError + 0.01 < minusError) side = 1;
      else if (minusError + 0.01 < plusError) side = -1;

      mem.avoidSide = side;
      mem.avoidHeading = wrap(heading + 78 * side);
      mem.avoidTicks = 39;
      mem.avoidBumped = false;
      avoiding = true;
      targetHeading = mem.avoidHeading;
    }
  }

  let base;
  if (avoiding) {
    base = clamp(0.72 + 0.50 * (1.5 - speed), -0.35, 0.82);
  } else {
    const targetSpeed = Math.sqrt(2 * Math.max(goalDist - 0.45, 0));
    base = clamp(0.93 + 0.65 * (targetSpeed - speed), -0.45, 0.98);
  }

  const errorRad = wrap(targetHeading - heading) * Math.PI / 180;
  const steer = clamp(0.55 * errorRad, -0.95, 0.95);

  return {
    left: clamp(base - steer, -1, 1),
    right: clamp(base + steer, -1, 1)
  };
}

