        if (tentative < gScore[ni]) {
          cameFrom[ni] = cur;
          gScore[ni] = tentative;
          fScore[ni] = tentative + h(nx, ny);
          push(ni, fScore[ni]);
        }
      }
    }

    if (!found) return null;

    const path = [];
    let cur = goal;
    while (cur !== start) {
      const cx = cur % N, cy = Math.floor(cur / N);
      path.push({ x: cx * CS + CS / 2, y: cy * CS + CS / 2 });
      cur = cameFrom[cur];
      if (cur < 0) break;
    }
    path.reverse();
    path.push({ x: goalX, y: goalY });
    return path;
  }

  const needPlan = !mem.path || mem.pathIndex >= mem.path.length || mem.mapChanged || (obs.t - mem.lastPlan > 2.0);
  if (needPlan) {
    const newPath = planPath(obs.x, obs.y, obs.goalX, obs.goalY);
    if (newPath) {
      mem.path = newPath;
      mem.pathIndex = 0;
    } else {
      mem.path = [{ x: obs.goalX, y: obs.goalY }];
      mem.pathIndex = 0;
    }
    mem.lastPlan = obs.t;
    mem.mapChanged = false;
  }

  let targetX, targetY;
  if (mem.path && mem.pathIndex < mem.path.length) {
    while (mem.pathIndex < mem.path.length - 1) {
      const wp = mem.path[mem.pathIndex];
      const d = Math.hypot(wp.x - obs.x, wp.y - obs.y);
      if (d < 0.8) mem.pathIndex++;
      else break;
    }
    const wp = mem.path[mem.pathIndex];
    targetX = wp.x;
    targetY = wp.y;
  } else {
    targetX = obs.goalX;
    targetY = obs.goalY;
  }

  const dx = targetX - obs.x;
  const dy = targetY - obs.y;
  const desired = Math.atan2(dy, dx) * 180 / PI;
  const err = norm(desired - obs.heading);
  const turn = clamp(err / 45, -1, 1);

  let v = 0.9;
  if (Math.abs(err) > 60) v = 0.4;
  else if (Math.abs(err) > 30) v = 0.6;
  else if (Math.abs(err) > 15) v = 0.8;

  if (obs.distanceAhead < 3.0) {
    const sf = clamp((obs.distanceAhead - 0.8) / 2.2, 0, 1);
    v = Math.min(v, 0.15 + 0.55 * sf);
  }
  const wallAhead = wallDistHeading(obs.x, obs.y, obs.heading);
  if (wallAhead < 2.5) {
    const sf = clamp((wallAhead - 0.8) / 1.7, 0, 1);
    v = Math.min(v, 0.1 + 0.5 * sf);
  }

  let left = v - turn * 0.7;
  let right = v + turn * 0.7;

  // Emergency reverse if about to hit something directly ahead
  if (obs.distanceAhead < 1.2 && obs.speed > 0.2) {
    left = -0.3;
    right = -0.3;
  }

  // Stall recovery
  if (obs.speed < 0.15) {
    if (!mem.stuckStart) mem.stuckStart = obs.t;
    else if (obs.t - mem.stuckStart > 1.0 && obs.t - mem.stuckStart < 2.0) {
      left = -0.5;
      right = -0.5;
    } else if (obs.t - mem.stuckStart >= 2.0) {
      mem.stuckStart = obs.t;
    }
  } else {
    mem.stuckStart = 0;
  }

  mem.lastLeft = mem.lastLeft * 0.6 + left * 0.4;
  mem.lastRight = mem.lastRight * 0.6 + right * 0.4;

  return {
    left: clamp(mem.lastLeft, -1, 1),
    right: clamp(mem.lastRight, -1, 1)
  };
}

function act(obs, mem) {
  const PI = Math.PI;
  const W = 40;

  function clamp(v, lo, hi) {
    return v < lo ? lo : (v > hi ? hi : v);
  }

  function norm(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }

  function wallDistHeading(x, y, heading) {
    const r = heading * PI / 180;
    const cx = Math.cos(r);
    const cy = Math.sin(r);
    let d = 1e9;
    if (cx > 1e-6) d = Math.min(d, (W - x) / cx);
    else if (cx < -1e-6) d = Math.min(d, (0 - x) / cx);
    if (cy > 1e-6) d = Math.min(d, (W - y) / cy);
    else if (cy < -1e-6) d = Math.min(d, (0 - y) / cy);
    if (!isFinite(d) || d < 0) d = 1e9;
    return d;
  }

  function chooseSide(obs, hx, hy, goalHeading, mem) {
    const bearing = Math.atan2(hy - obs.y, hx - obs.x) * 180 / PI;
    let bestS = mem.side || 1;
    let bestScore = Infinity;
    for (let s = -1; s <= 1; s += 2) {
      const cand = bearing + s * 80;
      let score = Math.abs(norm(goalHeading - cand)) * 0.15;
      const wd = wallDistHeading(obs.x, obs.y, cand);
      if (wd < 3.0) score += (3.0 - wd) * 20;
      if (score < bestScore) {
        bestScore = score;
        bestS = s;
      }
    }
    return bestS;
  }

  function safeHeading(obs, goalHeading, currentHeading) {
    const cands = [
      currentHeading,
      goalHeading,
      goalHeading + 45,
      goalHeading - 45,
      goalHeading + 90,
      goalHeading - 90,
      0, 90, 180, -90
    ];
    let best = currentHeading;
    let bestScore = -1e9;
    for (let i = 0; i < cands.length; i++) {
      const cand = cands[i];
      const wd = wallDistHeading(obs.x, obs.y, cand);
      if (wd < 0.6) continue;
      const score =
        Math.min(wd, 6) * 8 -
        Math.abs(norm(goalHeading - cand)) * 0.4 -
        Math.abs(norm(cand - currentHeading)) * 0.2;
      if (score > bestScore) {
        bestScore = score;
        best = cand;
      }
    }
    return best;
  }

  if (!mem.init) {
    mem.init = true;
    mem.state = 'goal';
    mem.side = 1;
    mem.avoidPoint = null;
    mem.avoidStart = 0;
    mem.clearStart = 0;
    mem.stuckStart = 0;
  }

  const dxg = obs.goalX - obs.x;
  const dyg = obs.goalY - obs.y;
  const distG = Math.hypot(dxg, dyg);
  if (distG < 0.9) return { left: 0, right: 0 };

  const hrad = obs.heading * PI / 180;
  const cosh = Math.cos(hrad);
  const sinh = Math.sin(hrad);
  const range = obs.distanceAhead;
  const wallAhead = wallDistHeading(obs.x, obs.y, obs.heading);
  const goalHeading = Math.atan2(dyg, dxg) * 180 / PI;

  let hit = null;
  if (range < 9.0 && wallAhead > range + 0.7) {
    const cx = obs.x + (range + 0.7) * cosh;
    const cy = obs.y + (range + 0.7) * sinh;
    if (cx > 0 && cx < W && cy > 0 && cy < W) {
      hit = { x: cx, y: cy };
    }
  }

  const obstacleAhead = hit && range < 6.0;

  if (mem.state === 'goal') {
    if (obstacleAhead) {
      mem.state = 'avoid';
      mem.avoidStart = obs.t;
      mem.avoidPoint = { x: hit.x, y: hit.y };
      mem.clearStart = 0;
      mem.side = chooseSide(obs, hit.x, hit.y, goalHeading, mem);
    }
  } else {
    if (hit && range < 7.0) {
      if (!mem.avoidPoint) {
        mem.avoidPoint = { x: hit.x, y: hit.y };
      } else {
        mem.avoidPoint.x = mem.avoidPoint.x * 0.7 + hit.x * 0.3;
        mem.avoidPoint.y = mem.avoidPoint.y * 0.7 + hit.y * 0.3;
      }
    }

    if (!obstacleAhead && range > 6.0) {
      if (mem.clearStart === 0) mem.clearStart = obs.t;
    } else {
      mem.clearStart = 0;
    }

    if (
      mem.clearStart !== 0 &&
      obs.t - mem.clearStart > 0.4 &&
      obs.t - mem.avoidStart > 0.8
    ) {
      const dTo = mem.avoidPoint
        ? Math.hypot(mem.avoidPoint.x - obs.x, mem.avoidPoint.y - obs.y)
        : 99;
      if (dTo > 3.2) {
        mem.state = 'goal';
        mem.avoidPoint = null;
      }
    }

    if (obs.t - mem.avoidStart > 12.0) {
      mem.state = 'goal';
      mem.avoidPoint = null;
    }
  }

  let target = goalHeading;
  let v = 0.85;

  if (mem.state === 'avoid') {
    if (mem.avoidPoint) {
      const b =
        Math.atan2(mem.avoidPoint.y - obs.y, mem.avoidPoint.x - obs.x) *
        180 / PI;
      target = b + mem.side * 80;
    }
    v = 0.6;
    if (range < 4.0) v = Math.min(v, 0.12 + 0.12 * range);
    if (range < 2.0) v = 0.04;
  } else {
    let vx = dxg / (distG || 1);
    let vy = dyg / (distG || 1);
    const margin = 1.5;
    if (obs.x < margin) vx += (margin - obs.x) * 1.5;
    if (obs.x > W - margin) vx -= (obs.x - (W - margin)) * 1.5;
    if (obs.y < margin) vy += (margin - obs.y) * 1.5;
    if (obs.y > W - margin) vy -= (obs.y - (W - margin)) * 1.5;

    target = Math.atan2(vy, vx) * 180 / PI;
    v = 0.85;
    if (distG < 2.5) {
      v *= 0.4 + 0.6 * clamp((distG - 0.9) / 1.6, 0, 1);
    }
  }

  if (
    wallAhead < 2.2 ||
    obs.x < 1.0 ||
    obs.x > W - 1.0 ||
    obs.y < 1.0 ||
    obs.y > W - 1.0
  ) {
    target = safeHeading(obs, goalHeading, obs.heading);
    v = Math.min(v, 0.4);
    if (wallAhead < 1.0) v = 0.05;
  }

  if (range < 4.0) {
    v = Math.min(v, 0.12 + 0.12 * range);
  }

  let emergency = false;
  if (range < 1.6) {
    v = 0;
    emergency = true;
  }

  const err = norm(target - obs.heading);
  const turn = clamp(err / 90, -0.8, 0.8);

  if (Math.abs(err) > 90) v = Math.min(v, 0.15);
  else if (Math.abs(err) > 45) v = Math.min(v, 0.35);

  let left = v - turn * 0.6;
  let right = v + turn * 0.6;

  if (emergency) {
    if (obs.speed > 0.15) {
      left = -0.5;
      right = -0.5;
    } else {
      left = -mem.side * 0.5;
      right = mem.side * 0.5;
    }
  } else if (wallAhead < 0.8 && obs.speed > 0.1) {
    left = -0.5;
    right = -0.5;
  }

  if (Math.abs(v) > 0.2 && obs.speed < 0.1 && !emergency) {
    if (!mem.stuckStart) {
      mem.stuckStart = obs.t;
    } else if (obs.t - mem.stuckStart > 1.2 && obs.t - mem.stuckStart < 1.8) {
      left = -0.5;
      right = -0.5;
    } else if (obs.t - mem.stuckStart >= 1.8) {
      mem.stuckStart = obs.t;
      mem.side = -mem.side;
    }
  } else {
    mem.stuckStart = 0;
  }

  left = clamp(left, -1, 1);
  right = clamp(right, -1, 1);

  return { left: left, right: right };
}

function act(obs, mem) {
  const PI = Math.PI;
  const W = 40;
  const N = 80;
  const CS = 0.5;

  function clamp(v, lo, hi) {
    return v < lo ? lo : (v > hi ? hi : v);
  }

  function norm(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }

  if (!mem.init) {
    mem.init = true;
    mem.blocked = new Uint8Array(N * N);
    for (let ix = 0; ix < N; ix++) {
      for (let iy = 0; iy < N; iy++) {
        const x = ix * CS + CS / 2;
        const y = iy * CS + CS / 2;
        if (x < 0.5 || x > W - 0.5 || y < 0.5 || y > W - 0.5) {
          mem.blocked[iy * N + ix] = 1;
        }
      }
    }
    mem.path = null;
    mem.pathIndex = 0;
    mem.lastPlan = -100;
    mem.mapChanged = false;
    mem.lastLeft = 0;
    mem.lastRight = 0;
    mem.stuckStart = 0;
  }

  function markDisk(x, y, r) {
    if (x < 0 || x > W || y < 0 || y > W) return false;
    const minX = Math.max(0, Math.floor((x - r) / CS));
    const maxX = Math.min(N - 1, Math.floor((x + r) / CS));
    const minY = Math.max(0, Math.floor((y - r) / CS));
    const maxY = Math.min(N - 1, Math.floor((y + r) / CS));
    const r2 = r * r;
    let changed = false;
    for (let iy = minY; iy <= maxY; iy++) {
      for (let ix = minX; ix <= maxX; ix++) {
        const cx = ix * CS + CS / 2;
        const cy = iy * CS + CS / 2;
        const dx = cx - x;
        const dy = cy - y;
        if (dx * dx + dy * dy <= r2) {
          const idx = iy * N + ix;
          if (!mem.blocked[idx]) {
            mem.blocked[idx] = 1;
            changed = true;
          }
        }
      }
    }
    return changed;
