  if (range < 9.8) {
    const rad = obs.heading * PI / 180;
    const ux = Math.cos(rad);
    const uy = Math.sin(rad);
    const hx = obs.x + range * ux;
    const hy = obs.y + range * uy;
    const nearWall = hx < 0.6 || hx > W - 0.6 || hy < 0.6 || hy > W - 0.6;
    if (!nearWall) {
      const cx = hx + 0.8 * ux;
      const cy = hy + 0.8 * uy;
