    let syi = clamp(Math.floor(sy / CS), 0, N - 1);
    let gxi = clamp(Math.floor(gx / CS), 0, N - 1);
    let gyi = clamp(Math.floor(gy / CS), 0, N - 1);

    function nearestFree(cx, cy, maxR) {
      for (let r = 0; r <= maxR; r++) {
        for (let dy = -r; dy <= r; dy++) {
          for (let dx = -r; dx <= r; dx++) {
            if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
            const nx = cx + dx;
            const ny = cy + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !mem.blocked[ny * N + nx]) {
              return { x: nx, y: ny };
            }
          }
        }
      }
      return null;
    }

