      const nf = nearestFree(sxi, syi, 5);
      if (nf) {
        sxi = nf.x;
        syi = nf.y;
      } else {
        return null;
      }
    }
    if (mem.blocked[gyi * N + gxi]) {
      const nf = nearestFree(gxi, gyi, 5);
      if (nf) {
        gxi = nf.x;
        gyi = nf.y;
      } else {
        return null;
      }
    }

    const start = syi * N + sxi;
    const goal = gyi * N + gxi;
    if (start === goal) return [{ x: gx, y: gy }];

    const size = N * N;
    if (!mem.gScore || mem.gScore.length !== size) {
      mem.gScore = new Float32Array(size);
      mem.fScore = new Float32Array(size);
      mem.cameFrom = new Int16Array(size);
      mem.closed = new Uint8Array(size);
