    const gScore = mem.gScore;
    const fScore = mem.fScore;
    const cameFrom = mem.cameFrom;
    const closed = mem.closed;
    gScore.fill(Infinity);
    fScore.fill(Infinity);
    cameFrom.fill(-1);
    closed.fill(0);

    const heap = [];
    function push(n) {
      heap.push(n);
      let i = heap.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (fScore[heap[p]] <= fScore[heap[i]]) break;
        const tmp = heap[p];
        heap[p] = heap[i];
        heap[i] = tmp;
        i = p;
      }
    }
    function pop() {
      const top = heap[0];
      const last = heap.pop();
      if (heap.length > 0) {
        heap[0] = last;
        let i = 0;
