  const err = norm(desired - obs.heading);
  const ae = Math.abs(err);

  let v = 1.0;
  if (ae > 100) v = 0.15;
  else if (ae > 60) v = 0.35;
  else if (ae > 30) v = 0.6;
  else if (ae > 15) v = 0.85;

