      mem.stuckStart = now;
    } else if (now - mem.stuckStart > 1.0 && now - mem.stuckStart < 1.6) {
      left = -0.5;
      right = -0.5;
    } else if (now - mem.stuckStart >= 1.6) {
      mem.stuckStart = now;
    }
  } else {
    mem.stuckStart = 0;
  }

  mem.lastLeft = mem.lastLeft * 0.5 + left * 0.5;
  mem.lastRight = mem.lastRight * 0.5 + right * 0.5;

  return {
    left: clamp(mem.lastLeft, -1, 1),
    right: clamp(mem.lastRight, -1, 1)
  };
}

function act(obs, mem) {
  const PI = Math.PI;
  const W = 40;
  function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
  function norm(a) { a = (a + 180) % 360; if (a < 0) a += 360; return a - 180; }

  if (!mem.init) {
    mem.init = true;
    mem.state = 'goal';
    mem.avoidWaypoint = null;
    mem.avoidStart = 0;
    mem.lastLeft = 0;
    mem.lastRight = 0;
    mem.stuckStart = 0;
    mem.obstacle = null;
    mem.ux = 0; mem.uy = 0;
  }

  const dxg = obs.goalX - obs.x;
  const dyg = obs.goalY - obs.y;
  const distG = Math.hypot(dxg, dyg);
  if (distG < 0.9) return { left: 0, right: 0 };

  const h = obs.heading * PI / 180;
  const range = obs.distanceAhead;

  let obstacle = null;
  if (range < 8.0 && range > 0.1) {
    const ox = obs.x + (range + 0.5) * Math.cos(h);
    const oy = obs.y + (range + 0.5) * Math.sin(h);
    if (ox > 0 && ox < W && oy > 0 && oy < W) {
      obstacle = { x: ox, y: oy };
    }
  }

  const now = obs.t;

  if (mem.state === 'goal') {
    if (obstacle && range < 4.0) {
      const goalBearing = Math.atan2(dyg, dxg) * 180 / PI;
      const obstBearing = obs.heading;
      let diff = norm(goalBearing - obstBearing);
      let side = diff >= 0 ? 1 : -1;
      if (Math.abs(diff) < 10) side = 1;
      const ux = Math.cos(h);
      const uy = Math.sin(h);
      const px = -uy;
      const py = ux;
      const forward = 2.0;
      const offset = 2.0;
      const wx = obstacle.x + ux * forward + side * px * offset;
      const wy = obstacle.y + uy * forward + side * py * offset;
      mem.state = 'avoid';
      mem.avoidWaypoint = { x: wx, y: wy };
      mem.avoidStart = now;
      mem.obstacle = obstacle;
      mem.ux = ux;
      mem.uy = uy;
    }
  } else if (mem.state === 'avoid') {
    const timeInAvoid = now - mem.avoidStart;
    const dToWaypoint = Math.hypot(mem.avoidWaypoint.x - obs.x, mem.avoidWaypoint.y - obs.y);
    let passed = false;
    if (mem.obstacle) {
      passed = (obs.x - mem.obstacle.x) * mem.ux + (obs.y - mem.obstacle.y) * mem.uy > 0.5;
    }
    if (dToWaypoint < 1.2 || passed || timeInAvoid > 5.0) {
      mem.state = 'goal';
      mem.avoidWaypoint = null;
      mem.obstacle = null;
    }
  }

  let tx = obs.goalX, ty = obs.goalY;
  if (mem.state === 'avoid' && mem.avoidWaypoint) {
    tx = mem.avoidWaypoint.x;
    ty = mem.avoidWaypoint.y;
  }

  let vx = tx - obs.x;
  let vy = ty - obs.y;
  const margin = 2.0;
  if (obs.x < margin) vx += (margin - obs.x) * 3.0;
  if (obs.x > W - margin) vx -= (obs.x - (W - margin)) * 3.0;
  if (obs.y < margin) vy += (margin - obs.y) * 3.0;
  if (obs.y > W - margin) vy -= (obs.y - (W - margin)) * 3.0;

  const desired = Math.atan2(vy, vx) * 180 / PI;
  const err = norm(desired - obs.heading);
  const ae = Math.abs(err);

  let v = 1.0;
  if (ae > 100) v = 0.2;
  else if (ae > 60) v = 0.4;
  else if (ae > 30) v = 0.7;
  else if (ae > 15) v = 0.9;

  if (range < 3.0) v = Math.min(v, 0.5);
  if (range < 1.5) v = Math.min(v, 0.2);
  if (distG < 1.5) v = Math.min(v, 0.3 + 0.5 * clamp((distG - 0.9) / 0.6, 0, 1));

  let steer = clamp(err / 90, -0.6, 0.6);

  let left = v - steer;
  let right = v + steer;

  mem.lastLeft = mem.lastLeft * 0.5 + left * 0.5;
  mem.lastRight = mem.lastRight * 0.5 + right * 0.5;
  left = clamp(mem.lastLeft, -1, 1);
  right = clamp(mem.lastRight, -1, 1);

  if (Math.abs(v) > 0.15 && obs.speed < 0.1) {
    if (!mem.stuckStart) mem.stuckStart = now;
    else if (now - mem.stuckStart > 1.0 && now - mem.stuckStart < 1.5) {
      left = -0.5;
      right = -0.5;
    } else if (now - mem.stuckStart >= 1.5) {
      mem.stuckStart = now;
    }
  } else {
    mem.stuckStart = 0;
  }

  return { left, right };
}

function act(obs, mem) {
  const PI = Math.PI;
  const W = 40;
  function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
  function norm(a) { a = (a + 180) % 360; if (a < 0) a += 360; return a - 180; }

  if (!mem.init) {
    mem.init = true;
    mem.mode = 'goal';
    mem.side = 1;
    mem.obsX = 0;
    mem.obsY = 0;
    mem.ux = 1;
    mem.uy = 0;
    mem.startT = 0;
    mem.lastLeft = 0;
    mem.lastRight = 0;
    mem.stuckStart = 0;
    mem.obstacles = [];
  }

  const h = obs.heading * PI / 180;
  const ux = Math.cos(h);
  const uy = Math.sin(h);
  const range = obs.distanceAhead;
  const dxg = obs.goalX - obs.x;
  const dyg = obs.goalY - obs.y;
  const distG = Math.hypot(dxg, dyg);

  if (distG < 0.9) return { left: 0, right: 0 };

  let hit = null;
  if (range < 9.5) {
    const hx = obs.x + range * ux;
    const hy = obs.y + range * uy;
    const nearWall = hx < 0.8 || hx > W - 0.8 || hy < 0.8 || hy > W - 0.8;
    if (!nearWall) {
      hit = { x: hx, y: hy };
      const cx = hx + ux * 1.2;
      const cy = hy + uy * 1.2;
      let found = false;
      for (let i = 0; i < mem.obstacles.length; i++) {
        const o = mem.obstacles[i];
        if (Math.hypot(o.x - cx, o.y - cy) < 1.2) {
          o.x = o.x * 0.7 + cx * 0.3;
          o.y = o.y * 0.7 + cy * 0.3;
          o.t = obs.t;
          found = true;
          break;
        }
      }
      if (!found) {
        mem.obstacles.push({ x: cx, y: cy, t: obs.t });
        if (mem.obstacles.length > 25) mem.obstacles.shift();
      }
    }
  }

  function chooseSide(tx, ty) {
    const gb = Math.atan2(ty - obs.y, tx - obs.x) * 180 / PI;
    const errG = norm(gb - obs.heading);
    if (Math.abs(errG) > 8) return errG > 0 ? 1 : -1;
    const px = -Math.sin(obs.heading * PI / 180);
    const py = Math.cos(obs.heading * PI / 180);
    const dot = (20 - obs.x) * px + (20 - obs.y) * py;
    return dot > 0 ? 1 : -1;
  }

  if (mem.mode === 'goal') {
    let trigger = null;
    if (hit) {
      trigger = { x: hit.x + ux * 1.2, y: hit.y + uy * 1.2 };
    } else {
      for (let i = 0; i < mem.obstacles.length; i++) {
        const o = mem.obstacles[i];
        const dx = o.x - obs.x;
        const dy = o.y - obs.y;
        const d = Math.hypot(dx, dy);
        if (d < 4.0) {
          const ang = Math.atan2(dy, dx) * 180 / PI;
          const err = norm(ang - obs.heading);
          if (Math.abs(err) < 60) {
            trigger = o;
            break;
          }
        }
      }
    }
    if (trigger && distG > 1.5) {
      mem.mode = 'avoid';
      mem.obsX = trigger.x;
      mem.obsY = trigger.y;
      mem.ux = ux;
      mem.uy = uy;
      mem.side = chooseSide(obs.goalX, obs.goalY);
      mem.startT = obs.t;
    }
  } else if (mem.mode === 'avoid') {
    if (hit) {
      const cx = hit.x + ux * 1.2;
      const cy = hit.y + uy * 1.2;
      const dToCurrent = Math.hypot(cx - mem.obsX, cy - mem.obsY);
      if (dToCurrent > 2.0 && range < 4.0) {
        mem.obsX = cx;
        mem.obsY = cy;
        mem.ux = ux;
        mem.uy = uy;
        mem.side = chooseSide(obs.goalX, obs.goalY);
        mem.startT = obs.t;
      }
    }
    const relX = obs.x - mem.obsX;
    const relY = obs.y - mem.obsY;
    const forwardProj = relX * mem.ux + relY * mem.uy;
    const distToObs = Math.hypot(relX, relY);
    if (forwardProj > 2.0 && distToObs > 2.8) {
      mem.mode = 'goal';
    }
    if (obs.t - mem.startT > 8.0) {
      mem.mode = 'goal';
    }
  }

  let targetX = obs.goalX;
  let targetY = obs.goalY;
  if (mem.mode === 'avoid') {
    const px = -mem.uy * mem.side;
    const py = mem.ux * mem.side;
    targetX = mem.obsX + mem.ux * 2.5 + px * 3.0;
    targetY = mem.obsY + mem.uy * 2.5 + py * 3.0;
  }

  let vx = targetX - obs.x;
  let vy = targetY - obs.y;
  const margin = 2.0;
  if (obs.x < margin) vx += (margin - obs.x) * 4.0;
  if (obs.x > W - margin) vx -= (obs.x - (W - margin)) * 4.0;
  if (obs.y < margin) vy += (margin - obs.y) * 4.0;
  if (obs.y > W - margin) vy -= (obs.y - (W - margin)) * 4.0;

  const desired = Math.atan2(vy, vx) * 180 / PI;
  const err = norm(desired - obs.heading);
  const ae = Math.abs(err);

  if (range < 1.0) {
    let side = mem.mode === 'avoid' ? mem.side : (err >= 0 ? 1 : -1);
    if (Math.abs(err) < 5) side = mem.side || 1;
    const left = -side * 0.5;
    const right = side * 0.5;
    mem.lastLeft = left;
    mem.lastRight = right;
    return { left, right };
  }

  if (ae > 120) {
    const side = err > 0 ? 1 : -1;
    const left = -side * 0.5;
    const right = side * 0.5;
    mem.lastLeft = left;
    mem.lastRight = right;
    return { left, right };
  }

  let v = mem.mode === 'avoid' ? 0.5 : 0.8;
  if (ae > 90) v *= 0.3;
  else if (ae > 45) v *= 0.5;
  else if (ae > 20) v *= 0.8;

  if (range < 6.0) {
    const safe = Math.max(0.1, (range - 1.0) * 0.7);
    v = Math.min(v, safe);
  }
  if (distG < 2.0) {
    v = Math.min(v, 0.3 + 0.5 * Math.max(0, (distG - 0.9) / 1.1));
  }

  if (range < 2.5 && obs.speed > 1.0) v = -0.5;
  if (range < 1.5 && obs.speed > 0.5) v = -0.6;

  let left, right;
  if (v < 0) {
    left = v;
    right = v;
  } else {
    const turn = clamp(err / 50, -1, 1);
    left = v * (1 - turn);
    right = v * (1 + turn);
  }

  if (Math.abs(v) > 0.15 && Math.abs(obs.speed) < 0.1) {
    if (!mem.stuckStart) mem.stuckStart = obs.t;
    else if (obs.t - mem.stuckStart > 1.0) {
      left = -0.3;
      right = -0.3;
      if (obs.t - mem.stuckStart > 1.5) mem.stuckStart = obs.t;
    }
  } else {
    mem.stuckStart = 0;
  }

  mem.lastLeft = mem.lastLeft * 0.5 + left * 0.5;
  mem.lastRight = mem.lastRight * 0.5 + right * 0.5;
  return {
    left: clamp(mem.lastLeft, -1, 1),
    right: clamp(mem.lastRight, -1, 1)
  };
}
